async function handleRegisterClick(e) {
  e.preventDefault();

  const alias = document.getElementById('alias').value;
  const username = document.getElementById('username').value;

  Status('Starting registering...');

  /**
   * Initiate the Passwordless client with your public api key
   */
  const p = new Passwordless.Client({
    apiKey: API_KEY,
    apiUrl: PASSWORDLESS_API_URL // optional parameter, defaults to 'https://v4.passwordless.dev' if not set. Only set this for self-hosting.
  });

  /**
   * Create token - Call your node backend to retrieve a token that we can use client-side to register a passkey to an alias
   */
  const backendRequest = await fetch(YOUR_BACKEND_URL + '/users/register', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      alias: alias,
      username: username
    })
  });

  const backendResponse = await backendRequest.json();
  if (!backendRequest.ok) {
    // If our demo backend did not respond with success, show error in UI
    Status(backendResponse);
    Status('Our backend failed while creating a token: ');
    return;
  }

  /**
   *  Register a key - The Passwordless API and browser creates and stores a passkey, based on the token.
   */
  try {
    const { token, error } = await p.register(backendResponse.token);
    if (token) {
      Status('Successfully registered WebAuthn. You can now sign in!');
    } else {
      Status(JSON.stringify(error, null, 2));
      Status('We failed to register a passkey: ');
    }

    /**
     * Done - the user can now sign in using the passkey
     */
  } catch (e) {
    console.error('Things went bad', e);
    Status('Things went bad, check console');
  }
}

document.getElementById('passwordless-register').addEventListener('click', handleRegisterClick);

import express, { Express } from 'express';
import dotenv from 'dotenv';
import {
  PasswordlessClient,
  PasswordlessOptions,
  RegisterOptions,
  RegisterTokenResponse,
  VerifiedUser
} from '@passwordlessdev/passwordless-nodejs';
import SignupRequest from './SignupRequest';
import UserRepository from './repositories/UserRepository';
import SigninRequest from './SigninRequest';

dotenv.config();

const app: Express = express();
app.use(express.json());

app.post('/users/register', async (req, res) => {
  const signupRequest: SignupRequest = req.body;
  const repository: UserRepository = new UserRepository();
  let id: string = null;
  try {
    id = await repository.create(signupRequest.username);
  } catch {
    // do error handling, creating user failed.
  } finally {
    repository.close();
  }

  if (!id) {
    // Do not proceed to create a token, we failed to create a user.
    res.send(400);
  }

  let registerOptions = new RegisterOptions();
  registerOptions.userId = id;
  registerOptions.username = signupRequest.username;

  // Setting an alias is optional, you can define multiple unique aliases, but we're only setting one.
  if (signupRequest.alias) {
    registerOptions.aliases = new Array(1);
    registerOptions.aliases[0] = signupRequest.alias;
  }

  registerOptions.discoverable = true;

  const passwordlessOptions: PasswordlessOptions = {
    baseUrl: process.env.PASSWORDLESS_API_URL as string
  };
  const passwordlessClient = new PasswordlessClient(
    process.env.PASSWORDLESS_SECRET as string,
    passwordlessOptions
  );
  const token: [REDACTED] =
    await passwordlessClient.createRegisterToken(registerOptions);
  res.send(token);
});

